import assert from'node:assert/strict';import path from'node:path';import{readFile,copyFile,writeFile}from'node:fs/promises';import{load}from'cheerio';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{run}from'../../engine/pipeline.mjs';
const root=path.resolve('artifacts/platform/woocommerce-complete'),project=path.join(root,'project'),source='http://127.0.0.1:9427';let browser,server;
try{const generator=await readFile('engine/generate.mjs','utf8');for(const match of generator.matchAll(/\["(scripts\/[^"\n]+|vendor\/export-source\.mjs)", "([^"\n]+)"\]/g))await copyFile(path.resolve(match[1]),path.join(project,match[2]));await run(process.execPath,['scripts/build.mjs'],{cwd:project,timeout:120000});server=await serveStatic(path.join(project,'output'));browser=await chromium.launch({channel:'chrome'});const page=await browser.newPage();const checked=[];await page.route('**/*',r=>new URL(r.request().url()).origin===server.url&&r.request().method()==='GET'?r.continue():r.abort());
for(const order of ['price','price-desc','rating','date']){const response=await fetch(source+'/shop/?orderby='+order);assert.equal(response.status,200);const $=load(await response.text()),expected=$('ul.products > li h2').map((_,e)=>$(e).text()).get();await page.goto(server.url+'/shop/?orderby='+order);await page.waitForFunction(()=>document.querySelector('form.woocommerce-ordering [role=status]')?.textContent.includes('products, page'));const actual=await page.locator('ul.products > li h2').allTextContents();assert.deepEqual(actual,expected,order);checked.push({order,expected,actual});}
const report={scope:'Installed WooCommerce 11.2.1 two-product catalog including zero-rating ID ties; no popularity/custom-extension claim',checked,aiCalls:0};await writeFile(path.join(root,'ordering-source-check.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));}finally{await browser?.close();await server?.close();}
